const items = $input.all();
const queries = [];

for (const item of items) {
  let outputStr = item.json.text || '';
  if (!outputStr && item.json.choices && item.json.choices[0] && item.json.choices[0].message) {
    outputStr = item.json.choices[0].message.content || '';
  }

  // Skip error/empty responses
  if (!outputStr || outputStr.trim() === '') {
    console.warn('Empty LLM response, skipping');
    continue;
  }

  // Strip thinking tags if present
  outputStr = outputStr.replace(/<think>[\s\S]*?<\/think>/gi, '').trim();

  // Clean markdown backticks
  outputStr = outputStr.replace(/^\s*```(json)?/mi, '').replace(/```\s*$/m, '').trim();

  let output = {};
  try {
    output = JSON.parse(outputStr);
  } catch(e) {
    const jsonMatch = outputStr.match(/\{[\s\S]*\}/);
    if (jsonMatch) {
      try {
        output = JSON.parse(jsonMatch[0]);
      } catch(e2) {
        console.warn('Failed to parse JSON output from LLM:', e2.message);
        continue;
      }
    } else {
      console.warn('No JSON found in LLM output');
      continue;
    }
  }

  const entities = output.entities || [];
  const relationships = output.relationships || [];

  let fileName = 'unknown';
  let rowHash = '';
  let fileHash = '';
  try {
    const rawItem = $('Loop Raw Items').item.json;
    fileName = rawItem.fileName || 'unknown';
    rowHash = rawItem.rowHash || '';
    fileHash = rawItem.fileHash || '';
  } catch(e) {
    console.warn('Could not read from Loop Raw Items:', e);
  }

  const clauses = [];
  let varIdx = 0;

  for (const entity of entities) {
    const label = entity.entity_type;
    const id = entity.canonical_id;
    const props = entity.properties || {};

    if (!label || !id) continue;

    const idField = label === 'Actor' ? 'actor_id' :
                   label === 'Location' ? 'location_code' :
                   label === 'ChargingStation' ? 'unit_id' :
                   label === 'Process' ? 'process_id' :
                   label === 'Material' ? 'material_id' : 'id';

    const v = `n${varIdx++}`;
    const setParts = Object.entries(props)
      .filter(([k, val]) => val !== null && val !== undefined && val !== '' && k !== idField)
      .map(([k, val]) => {
        const safeKey = k.replace(/`/g, '\\`');
        if (typeof val === 'number' || typeof val === 'boolean') {
          return `${v}.\`${safeKey}\` = ${val}`;
        }
        const safeVal = String(val).replace(/\\/g, '\\\\').replace(/'/g, "\\'");
        return `${v}.\`${safeKey}\` = '${safeVal}'`;
      });
    setParts.push(`${v}.ingested_at = datetime('${new Date().toISOString()}')`);
    setParts.push(`${v}.source_file = '${fileName}'`);
    setParts.push(`${v}.hash = '${rowHash || fileHash}'`);

    const safeId = String(id).replace(/\\/g, '\\\\').replace(/'/g, "\\'");
    clauses.push(`MERGE (${v}:${label} {${idField}: '${safeId}'}) SET ${setParts.join(', ')}`);
  }

  for (const rel of relationships) {
    if (!rel.from_type || !rel.from_id || !rel.to_type || !rel.to_id || !rel.relationship_type) continue;

    const fromField = rel.from_type === 'Actor' ? 'actor_id' :
                      rel.from_type === 'Location' ? 'location_code' :
                      rel.from_type === 'ChargingStation' ? 'unit_id' :
                      rel.from_type === 'Process' ? 'process_id' :
                      rel.from_type === 'Material' ? 'material_id' : 'id';
    const toField = rel.to_type === 'Actor' ? 'actor_id' :
                    rel.to_type === 'Location' ? 'location_code' :
                    rel.to_type === 'ChargingStation' ? 'unit_id' :
                    rel.to_type === 'Process' ? 'process_id' :
                    rel.to_type === 'Material' ? 'material_id' : 'id';

    const relProps = rel.properties || {};
    const relSetParts = [];
    const relVar = `r${varIdx++}`;
    const fromVar = `a${varIdx++}`;
    const toVar = `b${varIdx++}`;

    Object.entries(relProps)
      .filter(([k, val]) => val !== null && val !== undefined)
      .forEach(([k, val]) => {
        const safeKey = k.replace(/`/g, '\\`');
        if (typeof val === 'number' || typeof val === 'boolean') {
          relSetParts.push(`${relVar}.\`${safeKey}\` = ${val}`);
        } else {
          const safeVal = String(val).replace(/\\/g, '\\\\').replace(/'/g, "\\'");
          relSetParts.push(`${relVar}.\`${safeKey}\` = '${safeVal}'`);
        }
      });
    relSetParts.push(`${relVar}.ingested_at = datetime('${new Date().toISOString()}')`);
    relSetParts.push(`${relVar}.source_file = '${fileName}'`);

    const setClause = relSetParts.length > 0 ? ' SET ' + relSetParts.join(', ') : '';
    const safeFromId = String(rel.from_id).replace(/\\/g, '\\\\').replace(/'/g, "\\'");
    const safeToId = String(rel.to_id).replace(/\\/g, '\\\\').replace(/'/g, "\\'");

    clauses.push(`WITH 1 AS dummy MATCH (${fromVar}:${rel.from_type} {${fromField}: '${safeFromId}'}) MATCH (${toVar}:${rel.to_type} {${toField}: '${safeToId}'}) MERGE (${fromVar})-[${relVar}:${rel.relationship_type}]->(${toVar})${setClause}`);
  }

  if (clauses.length > 0) {
    const fullQuery = clauses.join('\n') + '\nRETURN 1 AS ok';
    queries.push({ json: { queryType: 'batch', cypher: fullQuery } });
  }
}

if (queries.length === 0) {
  queries.push({ json: { queryType: 'noop', cypher: 'RETURN 1 AS ok' } });
}

return queries;

const loopItems = $('Loop Raw Items').all();
const llm1Items = $('LLM Call 1: Create Prompt').all();
const llm2Items = $('LLM Call 2: Extract Entities').all();

const failedFiles = new Set();

// Check LLM 1 errors
for (let i = 0; i < llm1Items.length; i++) {
  const item = llm1Items[i];
  if (item.json.error) {
    const loopJson = loopItems[i]?.json || {};
    if (loopJson.fileName) failedFiles.add(loopJson.fileName);
  }
}

// Check LLM 2 errors
for (let i = 0; i < llm2Items.length; i++) {
  const item = llm2Items[i];
  if (item.json.error || !item.json.choices || !item.json.choices[0] || !item.json.choices[0].message || !item.json.choices[0].message.content) {
    const loopJson = loopItems[i]?.json || {};
    if (loopJson.fileName) failedFiles.add(loopJson.fileName);
  }
}

const items = $('Extract File Content').all();
const uniqueFiles = [];
const seen = new Set();
for (const item of items) {
  const json = item.json;
  if (json.fileName && json.fileHash && !seen.has(json.fileName) && !failedFiles.has(json.fileName)) {
    seen.add(json.fileName);
    uniqueFiles.push({ name: json.fileName, hash: json.fileHash });
  }
}
if (uniqueFiles.length === 0) {
  return [{ json: { query: "RETURN 1 AS ok" } }];
}
const mapStrings = uniqueFiles.map(f => `{name: '${f.name.replace(/'/g, "\\'")}', hash: '${f.hash}'}`).join(", ");
const query = `UNWIND [${mapStrings}] AS f MERGE (file:ProcessedFile {name: f.name}) SET file.hash = f.hash, file.ingested_at = datetime() RETURN file.name`;
return [{ json: { query } }];

const prompt = $('Loop Raw Items').item.json.prompt || "";
const db_actors = $json.db_actors || [];
const db_locations = $json.db_locations || [];
const db_stations = $json.db_stations || [];
const db_materials = $json.db_materials || [];

const payload = {
  model: "google/gemma-4-31B-it",
  messages: [
    {
      role: "system",
      content: "You are a database entity resolution assistant for a supply chain knowledge graph. Your task is to analyze raw input records and compare them against the provided \"Existing DB Entities\" list. Decide which names match existing entities and must map to those existing IDs (accounting for typos, abbreviations, casing, or company suffixes like GmbH/Corp), and which require generating new IDs according to the rules (Actors=A<n>, Locations=LOC_<3-LETTER>, ChargingStations=EVC-<year>-<n>, Materials=MAT_<n>, Processes=<unit_id>_<process_id>). Output ONLY a bulleted list of mapping rules, no markdown code block wrapper, no conversational text."
    },
    {
      role: "user",
      content: `Raw Record:\n${prompt}\n\nExisting DB Entities:\n- Actors: ${JSON.stringify(db_actors)}\n- Locations: ${JSON.stringify(db_locations)}\n- Stations: ${JSON.stringify(db_stations)}\n- Materials: ${JSON.stringify(db_materials)}`
    }
  ],
  temperature: 0.1,
  max_tokens: 4096
};

return [{ json: payload }];

const llm1_output = $json.choices && $json.choices[0] && $json.choices[0].message && $json.choices[0].message.content ? $json.choices[0].message.content : "";
const prompt = $('Loop Raw Items').item.json.prompt || "";

const payload = {
  model: "google/gemma-4-31B-it",
  messages: [
    {
      role: "system",
      content: "You are a precise supply chain knowledge graph entity extractor. Extract ALL entities and relationships from the input. Use the provided Mapping Instructions to resolve canonical IDs. Extract all attributes (e.g. cost_eur, duration_days, start_date, completion_date, status, serial_number, product_variant, manufacture_date, country, distance_km, carbon_kg_co2_eq) in the properties dictionary using the raw record field names as keys. Output ONLY valid JSON conforming strictly to the schema (no markdown backticks, no thinking tags). Schema: {\"entities\": [{\"entity_type\": \"Actor\"|\"Location\"|\"ChargingStation\"|\"Process\"|\"Material\"|\"Risk\"|\"MaintenanceEvent\"|\"TestReport\"|\"IncidentReport\"|\"AuditFinding\"|or any other relevant supply chain label, \"canonical_id\": \"ID\", \"properties\": {\"name\": \"...\", ...}}], \"relationships\": [{\"from_type\": \"...\", \"from_id\": \"...\", \"relationship_type\": \"LOCATED_IN\"|\"EXECUTED_BY\"|\"UNDERGOES\"|\"SUPPLIES\"|\"USES_MATERIAL\"|\"TESTED_BY\"|\"MAINTAINED_BY\"|\"RELATED_TO\"|or any other relevant relationship type, \"to_type\": \"...\", \"to_id\": \"...\", \"properties\": {}}]}"
    },
    {
      role: "user",
      content: `Mapping Instructions:\n${llm1_output}\n\nRaw Record to Extract:\n${prompt}`
    }
  ],
  temperature: 0.1,
  max_tokens: 8192
};

return [{ json: payload }];
